WITH target_info AS (
    SELECT tid, pref_name, organism AS assay_organism FROM target_dictionary WHERE pref_name = 'Orexin receptor type 2' AND chembl_id = 'CHEMBL4792' AND target_type = 'SINGLE PROTEIN' AND tax_id = 9606
), human_assays AS (
    SELECT a.assay_id, a.molecule_chembl_id, a.activity_id FROM activities a JOIN target_info t ON a.assay_id IN (SELECT assay_id FROM assays WHERE tid = t.tid AND assay_organism = 'Homo sapiens') WHERE a.standard_type = 'IC50' AND a.standard_units = 'nM' AND a.standard_value IS NOT NULL
)
SELECT DISTINCT md.chembl_id AS molecule_chembl_id, md.pref_name, cs.canonical_smiles FROM human_assays ha JOIN molecule_dictionary md ON ha.molecule_chembl_id = md.molecule_chembl_id JOIN molecule_structures cs ON ha.molecule_chembl_id = cs.molecule_chembl_id WHERE cs.canonical_smiles IS NOT NULL AND ha.standard_value IS NOT NULL;
